model.compile(optimizer='adam', loss='binary_crossentropy', metrics=['accuracy'])

# Prepare the training data properly
# The HuggingFace model expects input dictionaries with proper dtypes
def prepare_batch(batch):
    return {
        'input_ids': tf.cast(tf.stack([item['input_ids'] for item in batch]), tf.int32),
        'attention_mask': tf.cast(tf.stack([item['attention_mask'] for item in batch]), tf.int32),
        'token_type_ids': tf.cast(tf.stack([item['token_type_ids'] for item in batch]), tf.int32),
    }, tf.cast([item['label'] for item in batch], tf.float32)

# Convert data to batches
batch_size = 8
train_dataset = tf.data.Dataset.from_generator(
    lambda: [train_df.iloc[i:i+batch_size].to_dict('records') for i in range(0, len(train_df), batch_size)],
    output_signature=(
        tf.TensorSpec(shape=(None, None), dtype=tf.int32),
        tf.TensorSpec(shape=(None,), dtype=tf.float32)
    )
)

# Better approach: use the dataset format directly
